\begin{ex}%[8H9H2]
Tam giác $\Delta {AEG}$ có độ dài ${AE=21}$ cm, ${AG=26}$ cm, ${EG=25}$ cm. ${\Delta LMN \backsim \Delta AEG}$ và $\Delta LMN$ có chu vi bằng $288$ cm. Hãy tính độ dài các cạnh của $\Delta LMN$. 

\choice
{ \True  ${LM=84}$ cm; ${LN=104}$ cm; ${MN=100}$ cm }
   {  ${LM=83}$ cm; ${LN=103}$ cm; ${MN=99}$ cm }
     {  ${LM=86}$ cm; ${LN=103}$ cm; ${MN=98}$ cm }
    {  ${LM=85}$ cm; ${LN=105}$ cm; ${MN=101}$ cm }
\loigiai{
${\Delta LMN \backsim \Delta AEG}$\\
suy ra $\dfrac{LM}{AE}=\dfrac{LN}{AG}=\dfrac{NM}{GE}= \dfrac{LM+LN+NM}{AE+AG+GE}=\dfrac{288}{72}=4$\\
Vậy ${LM=84}$ cm; ${LN=104}$ cm; ${MN=100}$ cm
}\end{ex}

